// Des: Unit tests for per-job state files and once latch
// Flo: write state > read back > clear > assert exact
// I/O: job id + stats > files in a temp dir
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const stor = @import("tk-task-stor.zig");
const tszz = std.testing; const Task = stor.Task; const Reje = stor.Reje; const vali = stor.vali; const norm = stor.norm; const chaiFind = stor.chaiFind; const idenVali = stor.idenVali; const autoRunz = stor.autoRunz;
const conf = @import("store"); var data_bufz: [1024]u8 = undefined;
// point the state folder at a temp dir so tests never touch the real data folder
fn dataTemp(tmpz: *std.testing.TmpDir) void { var iozz_impl = std.Io.Threaded.init(tszz.allocator, .{}); defer iozz_impl.deinit(); const cwdz = std.process.currentPathAlloc(iozz_impl.io(), tszz.allocator) catch unreachable; defer tszz.allocator.free(cwdz); conf.tune.data = std.fmt.bufPrint(&data_bufz, "{s}{c}.zig-cache{c}tmp{c}{s}", .{ cwdz, std.fs.path.sep, std.fs.path.sep, std.fs.path.sep, tmpz.sub_path }) catch unreachable; }
fn testJson(allo: std.mem.Allocator, text: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, text, .{}) catch unreachable; }
test "chain progress file round-trips and clears" { var tmpd = tszz.tmpDir(.{}); defer tmpd.cleanup(); defer conf.tune = .{}; dataTemp(&tmpd); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); var iozz_impl = std.Io.Threaded.init(tszz.allocator, .{}); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); const allo = aren.allocator(); const iden = "zz-unit-chain-state"; stor.chaiStatClea(allo, iozz, iden); try tszz.expect(stor.chaiStatRead(allo, iozz, iden) == null); stor.chaiStatWrit(allo, iozz, iden, .{ .inde = 3, .ranz = 2, .fail = 1, .next_msec = 1_700_000_000_123, .star_msec = 1_699_999_999_000 }); const stat = stor.chaiStatRead(allo, iozz, iden).?; try tszz.expectEqual(@as(u32, 3), stat.inde); try tszz.expectEqual(@as(u32, 1), stat.fail); try tszz.expectEqual(@as(i64, 1_700_000_000_123), stat.next_msec); stor.chaiStatClea(allo, iozz, iden); try tszz.expect(stor.chaiStatRead(allo, iozz, iden) == null); }
test "once latch: absent -> written -> cleared" { var tmpd = tszz.tmpDir(.{}); defer tmpd.cleanup(); defer conf.tune = .{}; dataTemp(&tmpd); var iozz_impl = std.Io.Threaded.init(tszz.allocator, .{}); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const iden = "zz-unit-test-once-latch"; stor.onceFireClea(allo, iozz, iden); try tszz.expectEqualStrings("", stor.onceStamRead(allo, iozz, iden)); stor.onceFireMark(allo, iozz, iden, "260817_2017"); try tszz.expectEqualStrings("260817_2017", stor.onceStamRead(allo, iozz, iden)); try tszz.expect(!std.mem.eql(u8, stor.onceStamRead(allo, iozz, iden), "260818_0900")); stor.onceFireClea(allo, iozz, iden); try tszz.expectEqualStrings("", stor.onceStamRead(allo, iozz, iden)); }
test "once latch refuses a traversal id instead of writing outside its dir" { var tmpd = tszz.tmpDir(.{}); defer tmpd.cleanup(); defer conf.tune = .{}; dataTemp(&tmpd); var iozz_impl = std.Io.Threaded.init(tszz.allocator, .{}); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); stor.onceFireMark(allo, iozz, "../escaped", "260817_2017"); try tszz.expectEqualStrings("", stor.onceStamRead(allo, iozz, "../escaped")); }
